// The gadgets that hold text which can be changed: text fields and text areas.
//
// Text areas keep their text the way that the rich edit control of the original does: a line ends with Chr(13), and
// a position is the number of characters before it. What counts as a line is what is between two of those, text that
// is wrapped at the edge of a text area is still one line.

#include "gui_internal.hpp"
#include "runtime_internal.h"
#include "memory.h"

namespace bb::gui {
	// Turns all the ways to end a line into the one that text areas use.
	void normalize_text(const char* text, char** out, int* length)
	{
		size_t size = text ? strlen(text) : 0;
		char*  mem  = static_cast<char*>(bb_malloc(size + 1));
		if (!mem) {
			gui_error("Out of memory.");
		}
		size_t n = 0;
		for (size_t i = 0; i < size; i++) {
			if (text[i] == '\r') {
				mem[n++] = '\r';
				if ((i + 1 < size) && (text[i + 1] == '\n')) {
					i++;
				}
			} else if (text[i] == '\n') {
				mem[n++] = '\r';
			} else {
				mem[n++] = text[i];
			}
		}
		mem[n] = 0;
		*out    = mem;
		*length = int(n);
	}

	int text_area_length(gadget const& g)
	{
		return g.text ? int(strlen(g.text)) : 0;
	}

	// How many lines there are: an empty text has one.
	int line_count(gadget const& g)
	{
		int lines = 1;
		for (const char* p = g.text; p && *p; p++) {
			if (*p == '\r') {
				lines++;
			}
		}
		return lines;
	}

	// Where a line starts, or the length of the text for a line that is not there.
	int line_start(gadget const& g, int line)
	{
		if (line < 0) {
			return 0;
		}
		int length = text_area_length(g);
		if (line >= line_count(g)) {
			return length;
		}
		int at = 0;
		for (int i = 0; (i < length) && (at < line); i++) {
			if (g.text[i] == '\r') {
				at++;
				if (at == line) {
					return i + 1;
				}
			}
		}
		return 0;
	}

	int line_of(gadget const& g, int pos)
	{
		if (pos < 0) {
			return 0;
		}
		int length = text_area_length(g);
		if (pos > length) {
			return line_count(g);
		}
		int line = 0;
		for (int i = 0; i < pos; i++) {
			if (g.text[i] == '\r') {
				line++;
			}
		}
		return line;
	}

	// Moves the text that formats are for, when text is put in or taken out.
	static void shift_formats(gadget& g, int pos, int removed, int added)
	{
		for (uint32_t i = 0; i < g.formats.size;) {
			text_format& f = g.formats[i];
			int          end = f.pos + f.len;
			if (end <= pos) {
				i++;
				continue;
			}
			if (f.pos >= pos + removed) {
				f.pos += added - removed;
				i++;
				continue;
			}
			// The format overlaps what changed: what is left of it is kept.
			int keep_before = pos > f.pos ? pos - f.pos : 0;
			int keep_after  = end > pos + removed ? end - (pos + removed) : 0;
			int new_len     = keep_before + keep_after;
			if (new_len <= 0) {
				for (uint32_t k = i + 1; k < g.formats.size; k++) {
					g.formats[k - 1] = g.formats[k];
				}
				g.formats.size--;
				continue;
			}
			f.len = new_len;
			if (f.pos > pos) {
				f.pos = pos + added;
			}
			i++;
		}
	}

	// Puts text in place of what is between pos and pos + len.
	void text_area_insert(gadget& g, int pos, int len, const char* text)
	{
		int length = text_area_length(g);
		pos        = pos < 0 ? 0 : (pos > length ? length : pos);
		len        = (len < 0) || (pos + len > length) ? length - pos : len;
		char* added = nullptr;
		int   add   = 0;
		normalize_text(text, &added, &add);
		if (length - len + add > 1024 * 1024) {
			add = 1024 * 1024 - (length - len);
			if (add < 0) {
				add = 0;
			}
			added[add] = 0;
		}
		char* body = static_cast<char*>(bb_malloc(size_t(length - len + add) + 1));
		if (!body) {
			gui_error("Out of memory.");
		}
		memcpy(body, g.text, size_t(pos));
		memcpy(body + pos, added, size_t(add));
		memcpy(body + pos + add, g.text + pos + len, size_t(length - pos - len));
		body[length - len + add] = 0;
		bb_free(g.text);
		g.text = body;
		bb_free(added);
		shift_formats(g, pos, len, add);
		int total = length - len + add;
		// What was selected is kept, as far as it still exists.
		g.caret  = g.caret > total ? total : g.caret;
		g.anchor = g.anchor > total ? total : g.anchor;
		dirty();
	}

	void set_text_field(gadget& g, const char* text)
	{
		// A text field is one line, so what would end a line ends the text.
		char* fresh = copy_string(text);
		for (char* p = fresh; *p; p++) {
			if ((*p == '\r') || (*p == '\n')) {
				*p = 0;
				break;
			}
		}
		bb_free(g.text);
		g.text = fresh;
		int total = int(strlen(g.text));
		g.caret   = g.caret > total ? total : g.caret;
		g.anchor  = g.anchor > total ? total : g.anchor;
		dirty();
	}

	// Which range of characters a call means: what is asked for is made to fit in the text. In lines, the positions
	// are lines, and the range is the characters of those lines.
	static bool adjust_range(gadget const& g, int* pos, int* len, int units)
	{
		int total = units == 2 ? line_count(g) : text_area_length(g);
		if (*pos < 0) {
			*pos = 0;
		} else if (*pos > total) {
			*pos = total;
		}
		if ((*len < 0) || (*pos + *len > total)) {
			*len = total - *pos;
		}
		if (!*len) {
			return false;
		}
		if (units == 2) {
			int first = *pos;
			*pos      = line_start(g, first);
			*len      = line_start(g, first + *len) - *pos;
		}
		return true;
	}

	static gadget* area(int handle, const char* what)
	{
		return need_kind(handle, K_TEXTAREA, what);
	}
} // namespace bb::gui

using namespace bb::gui;

extern "C" {

const char* bb_text_field_text(int32_t handle)
{
	return string_result(need_kind(handle, K_TEXTFIELD, "TextFieldText")->text);
}

void bb_set_text_area_tabs(int32_t handle, int32_t tabs)
{
	gadget* g = area(handle, "SetTextAreaTabs");
	g->tabs   = tabs < 1 ? 1 : tabs;
	dirty();
}

void bb_set_text_area_font(int32_t handle, int32_t font)
{
	gadget* g = area(handle, "SetTextAreaFont");
	g->font   = font;
	dirty();
}

void bb_set_text_area_color(int32_t handle, int32_t r, int32_t green, int32_t b, int32_t background)
{
	gadget* g = area(handle, "SetTextAreaColor");
	if (background) {
		g->back_color[0] = r & 255;
		g->back_color[1] = green & 255;
		g->back_color[2] = b & 255;
		g->has_back      = true;
	} else {
		g->text_color[0]   = r & 255;
		g->text_color[1]   = green & 255;
		g->text_color[2]   = b & 255;
		g->has_text_color  = true;
	}
	dirty();
}

int32_t bb_text_area_len(int32_t handle, int32_t units)
{
	gadget* g = area(handle, "TextAreaLen");
	return units == 2 ? line_count(*g) : text_area_length(*g);
}

int32_t bb_text_area_line_len(int32_t handle, int32_t line)
{
	gadget* g = area(handle, "TextAreaLineLen");
	return line_start(*g, line + 1) - line_start(*g, line);
}

int32_t bb_text_area_char(int32_t handle, int32_t line)
{
	return line_start(*area(handle, "TextAreaChar"), line);
}

int32_t bb_text_area_line(int32_t handle, int32_t pos)
{
	return line_of(*area(handle, "TextAreaLine"), pos);
}

int32_t bb_text_area_cursor(int32_t handle, int32_t units)
{
	gadget* g   = area(handle, "TextAreaCursor");
	int     pos = g->caret < g->anchor ? g->caret : g->anchor;
	return units == 2 ? line_of(*g, pos) : pos;
}

int32_t bb_text_area_sel_len(int32_t handle, int32_t units)
{
	gadget* g  = area(handle, "TextAreaSelLen");
	int     lo = g->caret < g->anchor ? g->caret : g->anchor, hi = g->caret < g->anchor ? g->anchor : g->caret;
	if (units == 2) {
		return line_of(*g, hi) - line_of(*g, lo) + 1;
	}
	return hi - lo;
}

void bb_add_text_area_text(int32_t handle, const char* text)
{
	gadget* g = area(handle, "AddTextAreaText");
	int     n = text_area_length(*g);
	text_area_insert(*g, n, 0, text);
	g->caret = g->anchor = text_area_length(*g);
	caret_to_view(*g);
}

void bb_set_text_area_text(int32_t handle, const char* text, int32_t pos, int32_t len, int32_t units)
{
	gadget* g = area(handle, "SetTextAreaText");
	adjust_range(*g, &pos, &len, units);
	text_area_insert(*g, pos, len, text);
}

void bb_format_text_area_text(int32_t handle, int32_t r, int32_t green, int32_t b, int32_t flags, int32_t pos, int32_t len, int32_t units)
{
	gadget* g = area(handle, "FormatTextAreaText");
	if (!adjust_range(*g, &pos, &len, units)) {
		return;
	}
	// What was formatted there before is replaced.
	text_format fresh;
	fresh.pos   = pos;
	fresh.len   = len;
	fresh.r     = r & 255;
	fresh.g     = green & 255;
	fresh.b     = b & 255;
	fresh.flags = flags;
	buffer<text_format> kept;
	for (uint32_t i = 0; i < g->formats.size; i++) {
		text_format f = g->formats[i];
		int         end = f.pos + f.len;
		if ((end <= pos) || (f.pos >= pos + len)) {
			kept.push(f);
			continue;
		}
		if (f.pos < pos) {
			text_format before = f;
			before.len         = pos - f.pos;
			kept.push(before);
		}
		if (end > pos + len) {
			text_format after = f;
			after.pos         = pos + len;
			after.len         = end - (pos + len);
			kept.push(after);
		}
	}
	kept.push(fresh);
	g->formats.release();
	g->formats = kept;
	dirty();
}

const char* bb_text_area_text(int32_t handle, int32_t pos, int32_t len, int32_t units)
{
	gadget* g = area(handle, "TextAreaText");
	if (!adjust_range(*g, &pos, &len, units)) {
		return string_result("");
	}
	return bb_copy(g->text + pos, size_t(len));
}

void bb_lock_text_area(int32_t handle)
{
	area(handle, "LockTextArea")->locked++;
}

void bb_unlock_text_area(int32_t handle)
{
	gadget* g = area(handle, "UnlockTextArea");
	if (g->locked > 0) {
		g->locked--;
	}
}
}
